gguf.chat_template:
{#- 0826版本 -#}
{%- if not messages %}
    {{- raise_exception('No messages provided.') }}
{%- endif %}
{%- set enable_thinking = enable_thinking | default(true) %}

{#- Render a string or a list of text blocks. -#}
{%- macro render_content(content, context_name) %}
    {%- if content is string %}
        {{- content }}
    {%- elif content is none or content is undefined %}
        {{- '' }}
    {%- elif content is iterable and content is not mapping %}
        {%- for block in content %}
            {%- if block.type == 'text' %}
                {{- block.text }}
            {%- else %}
                {{- raise_exception('Unsupported ' ~ context_name ~ ' content block type: ' ~ (block.type | string)) }}
            {%- endif %}
        {%- endfor %}
    {%- else %}
        {{- raise_exception(context_name ~ ' content must be a string or a list of text blocks') }}
    {%- endif %}
{%- endmacro %}

{#- Default system prompt -#}
{%- set default_system = "you are a helpful assistant." %}

{#- The first message-level system is placed in the initial system block. -#}
{%- set ns = namespace(initial_system='') %}
{%- if messages[0].role == "system" %}
    {%- set ns.initial_system = render_content(messages[0].content, 'system') %}
{%- endif %}

{#- System block -#}
{{- '<｜start▁of▁sentence｜><|System|>' + '\n' + default_system }}
{%- if tools %}
    {{- '## Tools' + '\n' + 'You have access to the following functions:' + '\n' + '<tools>' }}
    {%- for tool in tools %}
        {{- '\n' + tool.function | tojson}}
    {%- endfor %}
    {{- '\n' + '</tools>' }}
{%- endif %}
{%- if ns.initial_system %}
    {{- '\n\n' + ns.initial_system }}
{%- endif %}
{{- '<｜end▁of▁sentence｜>'}}

{#- Conversation turns -#}
{%- for message in messages %}
    {%- if message.role == "system" %}
        {#- The first system message was consumed by the initial block. -#}
        {%- if not loop.first %}
            {{- '<｜start▁of▁sentence｜><|System|>\n' + render_content(message.content, 'system') + '<｜end▁of▁sentence｜>' }}
        {%- endif %}
    {%- elif message.role == "user" %}
        {{- '<｜start▁of▁sentence｜><|User|>' + render_content(message.content, 'user') + '<｜end▁of▁sentence｜>' }}
    {%- elif message.role == "assistant" %}
        {%- set assistant_content = render_content(message.content, 'assistant') %}
        {%- if message.reasoning_content is defined and message.reasoning_content %}
            {%- set reasoning_content = message.reasoning_content %}
        {%- else %}
            {%- set reasoning_content = '' %}
        {%- endif %}
        {{- '<｜start▁of▁sentence｜><|Bot|>'}}
        {%- if reasoning_content %}
            {{- '<think>' + reasoning_content + '</think>'}}
        {%- else %}
            {{- '</think>' }}
        {%- endif %}
        {%- if assistant_content %}
            {{- assistant_content }}
        {%- endif %}
        {%- if message.tool_calls is defined and message.tool_calls is not none %}
            {%- for tool_call in message.tool_calls %}
                {%- if tool_call.function.arguments is not mapping %}
                    {{- raise_exception('tool_call.function.arguments must be a dictionary; normalize JSON strings before apply_chat_template') }}
                {%- endif %}
                {%- set args = tool_call.function.arguments %}
                {{- '<tool_call>' + tool_call.function.name }}
                {%- for k, v in args.items() %}
                    {{- '<arg_key>' ~ k ~ '</arg_key><arg_value>' ~ (v if v is string else v | tojson) ~ '</arg_value>' }}
                {%- endfor %}
                {{- '</tool_call>' }}
            {%- endfor %}
        {%- endif %}
        {{- '<｜end▁of▁sentence｜>' }}
    {%- elif message.role == "tool" %}
        {%- if loop.previtem is undefined or loop.previtem.role != "tool" %}
            {{- '<｜start▁of▁sentence｜><|Tool|>' }}
        {%- endif %}
        {{- '<tool_response>' ~ message.content ~ '</tool_response>' }}
        {%- if loop.nextitem is undefined or loop.nextitem.role != "tool" %}
            {{- '<｜end▁of▁sentence｜>' }}
        {%- endif %}
    {%- else %}
        {{- raise_exception('Unsupported message role: ' ~ message.role) }}
    {%- endif %}
{%- endfor %}

{#- Generation prompt -#}
{%- if add_generation_prompt %}
    {{- '<｜start▁of▁sentence｜><|Bot|>' }}
    {%- if enable_thinking is defined and enable_thinking %}
        {{- '<think>' }}
    {%- endif %}
    {%- if enable_thinking is defined and not enable_thinking %}
        {{- '</think>' }}
    {%- endif %}
{%- endif %}

{%- macro render_value(value) -%}
    {%- if value is string -%}
        {{- value -}}
    {%- else -%}
        {{- value | tojson(ensure_ascii=False) -}}
    {%- endif -%}
{%- endmacro -%}

{%- macro render_content(message_content) -%}
    {%- if message_content is string -%}
        {{- message_content -}}
    {%- elif message_content is iterable -%}
        {%- for part in message_content -%}
            {%- if part is not mapping -%}
                {{- part -}}
            {%- elif part['type'] == 'image' or 'image' in part or 'image_url' in part -%}
                {{- '<|vision_start|><|image_pad|><|vision_end|>' -}}
            {%- elif part['type'] == 'audio' or part['type'] == 'input_audio' or 'audio' in part or 'audio_url' in part or 'input_audio' in part -%}
                {{- '<|mimo_audio_start|><|audio_pad|><|mimo_audio_end|>' -}}
            {%- elif part['type'] == 'video' or 'video' in part or 'video_url' in part -%}
                {{- '<|vision_start|><|video_pad|><|vision_end|>' -}}
            {%- elif 'text' in part -%}
                {{- part['text'] -}}
            {%- endif -%}
        {%- endfor -%}
    {%- endif -%}
{%- endmacro -%}

{%- macro render_tools(tools) -%}
    {{- 'You are provided with the following tools:\n\n<tools>' -}}
    {%- for tool in tools -%}
        {{- '\n' ~ (tool | tojson(ensure_ascii=False)) -}}
    {%- endfor -%}
    {{- '\n</tools>' -}}
{%- endmacro -%}

{%- macro render_tool_calls(tool_calls) -%}
    {%- for tool_call in tool_calls -%}
        {%- if tool_call.function is defined -%}
            {%- set tool_call = tool_call.function -%}
        {%- elif tool_call.custom is defined -%}
            {%- set tool_call = tool_call.custom -%}
        {%- endif -%}
        {{- '<tool_call><function=' ~ tool_call.name ~ '>' -}}
        {%- if tool_call.input is defined and tool_call.input is string -%}
            {{- tool_call.input -}}
        {%- elif tool_call.arguments -%}
            {%- if tool_call.arguments is string -%}
                {{- tool_call.arguments -}}
            {%- else -%}
                {%- for args_name, args_value in tool_call.arguments | items -%}
                    {{- '<parameter=' ~ args_name ~ '>' ~ render_value(args_value) ~ '</parameter>' -}}
                {%- endfor -%}
            {%- endif -%}
        {%- endif -%}
        {{- '</function></tool_call>' -}}
    {%- endfor -%}
{%- endmacro -%}

{%- macro render_assistant_message(message) -%}
    {%- generation -%}
    {%- set content = render_content(message.content) -%}
    {%- set reasoning = message.reasoning_content if message.reasoning_content is string else '' -%}
    {{- '<|im_start|>assistant\n<think>' ~ reasoning ~ '</think>' ~ content -}}
    {%- if message.tool_calls is defined and message.tool_calls is iterable and message.tool_calls | length > 0 -%}
        {{- render_tool_calls(message.tool_calls) -}}
    {%- endif -%}
    {{- '<|im_end|>' -}}
    {%- endgeneration -%}
{%- endmacro -%}

{%- if tools is defined and tools is iterable and tools | length > 0 -%}
    {{- '<|im_start|>system\n' ~ render_tools(tools) ~ '<|im_end|>' -}}
{%- endif -%}

{%- for message in messages -%}
    {%- if message.role == 'assistant' -%}
        {{- render_assistant_message(message) -}}
    {%- else -%}
        {%- set body = render_content(message.content) -%}
        {{- '<|im_start|>' ~ message.role ~ '\n' ~ body -}}
        {%- if message.tools is defined and message.tools is iterable and message.tools | length > 0 -%}
            {%- if body -%}
                {{- '\n\n' -}}
            {%- endif -%}
            {{- render_tools(message.tools) -}}
        {%- endif -%}
        {{- '<|im_end|>' -}}
    {%- endif -%}
{%- endfor -%}

{%- if add_generation_prompt -%}
    {{- '<|im_start|>assistant\n' -}}
    {%- if enable_thinking is false -%}
        {{- '<think></think>' -}}
    {%- endif -%}
{%- endif -%}
